/**
 * CLI script that validates JSON input from stdin.
 * Exits with code 0 for valid JSON, 1 for invalid or empty input.
 */

const input = await Bun.stdin.text();

if (!input.trim()) {
  console.error("Error: No input provided.");
  process.exit(1);
}

try {
  JSON.parse(input);
  console.log("Valid JSON.");
  process.exit(0);
} catch {
  console.error("Invalid JSON.");
  process.exit(1);
}

import { describe, expect, test } from "bun:test";
import { resolve } from "path";

const scriptPath = resolve(import.meta.dir, "validate-json.ts");

async function runValidator(input: string): Promise<{ stdout: string; stderr: string; exitCode: number }> {
  const proc = Bun.spawn(["bun", "run", scriptPath], {
    stdin: new Response(input),
    stdout: "pipe",
    stderr: "pipe",
  });

  const [stdout, stderr] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
  ]);
  const exitCode = await proc.exited;

  return { stdout: stdout.trim(), stderr: stderr.trim(), exitCode };
}

describe("validate-json", () => {
  test("exits 0 and prints success for valid JSON object", async () => {
    const result = await runValidator('{"key": "value"}');
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toBe("Valid JSON.");
  });

  test("exits 0 for valid JSON array", async () => {
    const result = await runValidator('[1, 2, 3]');
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toBe("Valid JSON.");
  });

  test("exits 0 for valid JSON primitive", async () => {
    const result = await runValidator('"hello"');
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toBe("Valid JSON.");
  });

  test("exits 1 and prints error for invalid JSON", async () => {
    const result = await runValidator("{bad json}");
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toBe("Invalid JSON.");
  });

  test("exits 1 and prints error for empty input", async () => {
    const result = await runValidator("");
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toBe("Error: No input provided.");
  });

  test("exits 1 for whitespace-only input", async () => {
    const result = await runValidator("   \n  ");
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toBe("Error: No input provided.");
  });
});

