/**
 * Ultra-performant JSON validation engine.
 *
 * Uses compiled schema validators with iterative traversal,
 * pre-allocated error collection, and optional fast-fail mode.
 */

export type SchemaType =
  | "string"
  | "number"
  | "boolean"
  | "array"
  | "object"
  | "null";

export interface SchemaDefinition {
  type: SchemaType;
  properties?: Record<string, SchemaDefinition>;
  items?: SchemaDefinition;
  enum?: readonly unknown[];
  optional?: boolean;
  required?: string[];
}

export interface ValidationError {
  path: string;
  message: string;
}

export interface ValidationOptions {
  fastFail?: boolean;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

export type CompiledValidator = (
  data: unknown,
  options?: ValidationOptions,
) => ValidationResult;

interface StackFrame {
  schema: SchemaDefinition;
  data: unknown;
  pathSegments: string[];
}

const TYPE_CHECKERS: Record<SchemaType, (v: unknown) => boolean> = {
  string: (v): v is string => typeof v === "string",
  number: (v): v is number => typeof v === "number",
  boolean: (v): v is boolean => typeof v === "boolean",
  null: (v): v is null => v === null,
  array: (v): v is unknown[] => Array.isArray(v),
  object: (v): v is Record<string, unknown> =>
    v !== null && typeof v === "object" && !Array.isArray(v),
};

function buildPath(segments: string[]): string {
  if (segments.length === 0) return "$";
  let result = "$";
  for (let i = 0; i < segments.length; i++) {
    result += "." + segments[i];
  }
  return result;
}

/**
 * Pre-compile a schema into an optimized validator closure.
 * The compiled validator uses iterative stack-based traversal
 * to avoid deep recursion and pre-allocates error arrays.
 */
export function compileSchema(schema: SchemaDefinition): CompiledValidator {
  const rootSchema = schema;

  const precompiledCheckers = new Map<SchemaDefinition, (v: unknown) => boolean>();
  const precompiledEnumSets = new Map<SchemaDefinition, Set<unknown>>();
  const precompiledRequiredSets = new Map<SchemaDefinition, Set<string>>();
  const precompiledPropertyKeys = new Map<SchemaDefinition, string[]>();

  function preprocess(s: SchemaDefinition): void {
    precompiledCheckers.set(s, TYPE_CHECKERS[s.type]);

    if (s.enum !== undefined) {
      precompiledEnumSets.set(s, new Set(s.enum));
    }

    if (s.type === "object") {
      if (s.required) {
        precompiledRequiredSets.set(s, new Set(s.required));
      }
      if (s.properties) {
        const keys = Object.keys(s.properties);
        precompiledPropertyKeys.set(s, keys);
        for (let i = 0; i < keys.length; i++) {
          preprocess(s.properties[keys[i]]);
        }
      }
    }

    if (s.type === "array" && s.items) {
      preprocess(s.items);
    }
  }

  preprocess(rootSchema);

  return function validate(
    data: unknown,
    options?: ValidationOptions,
  ): ValidationResult {
    const fastFail = options?.fastFail === true;
    const errors: ValidationError[] = [];
    const stack: StackFrame[] = [
      { schema: rootSchema, data, pathSegments: [] },
    ];

    while (stack.length > 0) {
      const frame = stack.pop()!;
      const { schema: currentSchema, data: currentData, pathSegments } = frame;

      if (
        currentSchema.optional === true &&
        currentData === undefined
      ) {
        continue;
      }

      if (currentData === undefined) {
        errors.push({
          path: buildPath(pathSegments),
          message: "Value is required",
        });
        if (fastFail) break;
        continue;
      }

      const typeChecker = precompiledCheckers.get(currentSchema)!;
      if (!typeChecker(currentData)) {
        errors.push({
          path: buildPath(pathSegments),
          message: `Expected type "${currentSchema.type}" but got "${currentData === null ? "null" : Array.isArray(currentData) ? "array" : typeof currentData}"`,
        });
        if (fastFail) break;
        continue;
      }

      const enumSet = precompiledEnumSets.get(currentSchema);
      if (enumSet !== undefined && !enumSet.has(currentData)) {
        errors.push({
          path: buildPath(pathSegments),
          message: `Value must be one of: ${JSON.stringify([...enumSet])}`,
        });
        if (fastFail) break;
        continue;
      }

      if (currentSchema.type === "object" && currentSchema.properties) {
        const obj = currentData as Record<string, unknown>;
        const requiredSet = precompiledRequiredSets.get(currentSchema);
        const propKeys = precompiledPropertyKeys.get(currentSchema)!;

        if (requiredSet) {
          for (const reqKey of requiredSet) {
            if (!(reqKey in obj)) {
              errors.push({
                path: buildPath(pathSegments),
                message: `Missing required property "${reqKey}"`,
              });
              if (fastFail) {
                stack.length = 0;
                break;
              }
            }
          }
          if (fastFail && errors.length > 0) break;
        }

        for (let i = propKeys.length - 1; i >= 0; i--) {
          const key = propKeys[i];
          const propSchema = currentSchema.properties![key];
          const childSegments = pathSegments.slice();
          childSegments.push(key);
          stack.push({
            schema: propSchema,
            data: obj[key],
            pathSegments: childSegments,
          });
        }
      }

      if (currentSchema.type === "array" && currentSchema.items) {
        const arr = currentData as unknown[];
        for (let i = arr.length - 1; i >= 0; i--) {
          const childSegments = pathSegments.slice();
          childSegments.push(String(i));
          stack.push({
            schema: currentSchema.items,
            data: arr[i],
            pathSegments: childSegments,
          });
        }
      }
    }

    return { valid: errors.length === 0, errors };
  };
}

/**
 * Validate JSON data against a schema definition.
 * Compiles the schema and runs validation in a single call.
 * For repeated validation against the same schema, prefer
 * `compileSchema` followed by calling the returned validator.
 */
export function validateJson(
  schema: SchemaDefinition,
  data: unknown,
  options?: ValidationOptions,
): ValidationResult {
  const validator = compileSchema(schema);
  return validator(data, options);
}

import { describe, expect, test } from "bun:test";
import {
  compileSchema,
  validateJson,
  type SchemaDefinition,
} from "./validate-json";

describe("validate-json", () => {
  describe("string type", () => {
    const schema: SchemaDefinition = { type: "string" };

    test("accepts valid string", () => {
      const result = validateJson(schema, "hello");
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("rejects number", () => {
      const result = validateJson(schema, 42);
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain('Expected type "string"');
    });

    test("accepts empty string", () => {
      const result = validateJson(schema, "");
      expect(result.valid).toBe(true);
    });
  });

  describe("number type", () => {
    const schema: SchemaDefinition = { type: "number" };

    test("accepts valid number", () => {
      const result = validateJson(schema, 42);
      expect(result.valid).toBe(true);
    });

    test("accepts zero", () => {
      const result = validateJson(schema, 0);
      expect(result.valid).toBe(true);
    });

    test("accepts negative number", () => {
      const result = validateJson(schema, -3.14);
      expect(result.valid).toBe(true);
    });

    test("rejects string", () => {
      const result = validateJson(schema, "42");
      expect(result.valid).toBe(false);
    });
  });

  describe("boolean type", () => {
    const schema: SchemaDefinition = { type: "boolean" };

    test("accepts true", () => {
      const result = validateJson(schema, true);
      expect(result.valid).toBe(true);
    });

    test("accepts false", () => {
      const result = validateJson(schema, false);
      expect(result.valid).toBe(true);
    });

    test("rejects truthy number", () => {
      const result = validateJson(schema, 1);
      expect(result.valid).toBe(false);
    });
  });

  describe("null type", () => {
    const schema: SchemaDefinition = { type: "null" };

    test("accepts null", () => {
      const result = validateJson(schema, null);
      expect(result.valid).toBe(true);
    });

    test("rejects undefined", () => {
      const result = validateJson(schema, undefined);
      expect(result.valid).toBe(false);
    });

    test("rejects empty string", () => {
      const result = validateJson(schema, "");
      expect(result.valid).toBe(false);
    });
  });

  describe("array type", () => {
    const schema: SchemaDefinition = {
      type: "array",
      items: { type: "number" },
    };

    test("accepts valid array", () => {
      const result = validateJson(schema, [1, 2, 3]);
      expect(result.valid).toBe(true);
    });

    test("accepts empty array", () => {
      const result = validateJson(schema, []);
      expect(result.valid).toBe(true);
    });

    test("rejects array with wrong item types", () => {
      const result = validateJson(schema, [1, "two", 3]);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].path).toBe("$.1");
    });

    test("rejects non-array", () => {
      const result = validateJson(schema, "not an array");
      expect(result.valid).toBe(false);
    });

    test("rejects object as array", () => {
      const result = validateJson(schema, { length: 0 });
      expect(result.valid).toBe(false);
    });
  });

  describe("object type", () => {
    const schema: SchemaDefinition = {
      type: "object",
      properties: {
        name: { type: "string" },
        age: { type: "number" },
      },
      required: ["name"],
    };

    test("accepts valid object", () => {
      const result = validateJson(schema, { name: "Alice", age: 30 });
      expect(result.valid).toBe(true);
    });

    test("rejects missing required property", () => {
      const result = validateJson(schema, { age: 30 });
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Missing required");
    });

    test("accepts empty object when no required fields reference missing props", () => {
      const noRequiredSchema: SchemaDefinition = {
        type: "object",
        properties: {
          name: { type: "string", optional: true },
        },
      };
      const result = validateJson(noRequiredSchema, {});
      expect(result.valid).toBe(true);
    });

    test("accepts object with wrong-type property", () => {
      const result = validateJson(schema, { name: 123, age: 30 });
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("$.name");
    });

    test("rejects null as object", () => {
      const result = validateJson(schema, null);
      expect(result.valid).toBe(false);
    });

    test("rejects array as object", () => {
      const result = validateJson(schema, []);
      expect(result.valid).toBe(false);
    });
  });

  describe("nested object validation", () => {
    const schema: SchemaDefinition = {
      type: "object",
      properties: {
        user: {
          type: "object",
          properties: {
            name: { type: "string" },
            address: {
              type: "object",
              properties: {
                street: { type: "string" },
                city: { type: "string" },
              },
              required: ["street", "city"],
            },
          },
          required: ["name", "address"],
        },
      },
      required: ["user"],
    };

    test("accepts valid nested object", () => {
      const data = {
        user: {
          name: "Alice",
          address: { street: "123 Main St", city: "Springfield" },
        },
      };
      const result = validateJson(schema, data);
      expect(result.valid).toBe(true);
    });

    test("rejects invalid nested property", () => {
      const data = {
        user: {
          name: "Alice",
          address: { street: 123, city: "Springfield" },
        },
      };
      const result = validateJson(schema, data);
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("$.user.address.street");
    });
  });

  describe("nested array validation", () => {
    const schema: SchemaDefinition = {
      type: "array",
      items: {
        type: "array",
        items: { type: "number" },
      },
    };

    test("accepts valid nested arrays", () => {
      const result = validateJson(schema, [[1, 2], [3, 4]]);
      expect(result.valid).toBe(true);
    });

    test("rejects invalid item in nested array", () => {
      const result = validateJson(schema, [[1, 2], [3, "four"]]);
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("$.1.1");
    });
  });

  describe("optional fields", () => {
    const schema: SchemaDefinition = {
      type: "object",
      properties: {
        name: { type: "string" },
        nickname: { type: "string", optional: true },
      },
      required: ["name"],
    };

    test("accepts when optional field is missing", () => {
      const result = validateJson(schema, { name: "Alice" });
      expect(result.valid).toBe(true);
    });

    test("accepts when optional field is present and valid", () => {
      const result = validateJson(schema, { name: "Alice", nickname: "Ali" });
      expect(result.valid).toBe(true);
    });

    test("rejects when optional field is present but wrong type", () => {
      const result = validateJson(schema, { name: "Alice", nickname: 42 });
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("$.nickname");
    });
  });

  describe("enum values", () => {
    const schema: SchemaDefinition = {
      type: "string",
      enum: ["red", "green", "blue"],
    };

    test("accepts valid enum value", () => {
      const result = validateJson(schema, "red");
      expect(result.valid).toBe(true);
    });

    test("rejects invalid enum value", () => {
      const result = validateJson(schema, "yellow");
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("must be one of");
    });

    test("rejects wrong type even if enum matches", () => {
      const numEnumSchema: SchemaDefinition = {
        type: "number",
        enum: [1, 2, 3],
      };
      const result = validateJson(numEnumSchema, "1");
      expect(result.valid).toBe(false);
    });
  });

  describe("edge cases", () => {
    test("empty object with no schema properties", () => {
      const schema: SchemaDefinition = { type: "object" };
      const result = validateJson(schema, {});
      expect(result.valid).toBe(true);
    });

    test("empty array with no items schema", () => {
      const schema: SchemaDefinition = { type: "array" };
      const result = validateJson(schema, []);
      expect(result.valid).toBe(true);
    });

    test("null handling in object property", () => {
      const schema: SchemaDefinition = {
        type: "object",
        properties: {
          value: { type: "null" },
        },
        required: ["value"],
      };
      const result = validateJson(schema, { value: null });
      expect(result.valid).toBe(true);
    });

    test("collects multiple errors", () => {
      const schema: SchemaDefinition = {
        type: "object",
        properties: {
          a: { type: "string" },
          b: { type: "number" },
          c: { type: "boolean" },
        },
        required: ["a", "b", "c"],
      };
      const result = validateJson(schema, { a: 1, b: "two", c: "three" });
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThanOrEqual(3);
    });
  });

  describe("fastFail mode", () => {
    const schema: SchemaDefinition = {
      type: "object",
      properties: {
        a: { type: "string" },
        b: { type: "number" },
        c: { type: "boolean" },
      },
      required: ["a", "b", "c"],
    };

    test("returns single error in fastFail mode", () => {
      const result = validateJson(schema, { a: 1, b: "two", c: "three" }, { fastFail: true });
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
    });

    test("returns all errors without fastFail", () => {
      const result = validateJson(schema, { a: 1, b: "two", c: "three" });
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(1);
    });

    test("fastFail on missing required property", () => {
      const result = validateJson(schema, {}, { fastFail: true });
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
    });
  });

  describe("compileSchema reuse", () => {
    test("compiled validator can be reused", () => {
      const schema: SchemaDefinition = { type: "string" };
      const validator = compileSchema(schema);

      expect(validator("hello").valid).toBe(true);
      expect(validator(42).valid).toBe(false);
      expect(validator("world").valid).toBe(true);
    });
  });

  describe("performance benchmark", () => {
    const complexSchema: SchemaDefinition = {
      type: "object",
      properties: {
        id: { type: "number" },
        name: { type: "string" },
        active: { type: "boolean" },
        tags: {
          type: "array",
          items: { type: "string" },
        },
        metadata: {
          type: "object",
          properties: {
            createdAt: { type: "string" },
            updatedAt: { type: "string" },
            version: { type: "number" },
            flags: {
              type: "object",
              properties: {
                experimental: { type: "boolean" },
                deprecated: { type: "boolean" },
              },
              required: ["experimental", "deprecated"],
            },
          },
          required: ["createdAt", "version"],
        },
        scores: {
          type: "array",
          items: { type: "number" },
        },
      },
      required: ["id", "name", "active", "metadata"],
    };

    const validData = {
      id: 1,
      name: "Test Entity",
      active: true,
      tags: ["alpha", "beta", "gamma"],
      metadata: {
        createdAt: "2026-01-01T00:00:00Z",
        updatedAt: "2026-02-01T00:00:00Z",
        version: 3,
        flags: {
          experimental: false,
          deprecated: false,
        },
      },
      scores: [95, 87, 92, 88, 91],
    };

    test("validates 10,000 complex objects under 500ms", () => {
      const validator = compileSchema(complexSchema);
      const iterations = 10_000;

      const startNs = Bun.nanoseconds();
      for (let i = 0; i < iterations; i++) {
        validator(validData);
      }
      const elapsedMs = (Bun.nanoseconds() - startNs) / 1_000_000;

      expect(elapsedMs).toBeLessThan(500);
    });
  });
});

